                "code": "Example:\n Use the useState Hook to manage the input:\n\nimport { useState } from 'react';\nimport { createRoot } from 'react-dom/client';\n\nfunction MyForm() {\n const [inputs, setInputs] = useState({});\n\n const handleChange = (e) => {\n const name = e.target.name;\n const value = e.target.value;\n setInputs(values => ({...values, [name]: value}))\n }\n\n return (\n <form>\n <label>First name:\n <input \n type=\"text\" \n name=\"firstname\" \n value={inputs.firstname} \n onChange={handleChange}\n />\n </label>\n <label>Last name:\n <input \n type=\"text\" \n name=\"lastname\" \n value={inputs.lastname} \n onChange={handleChange}\n />\n </label>\n <p>Current values: {inputs.firstname} {inputs.lastname}</p>\n </form>\n )\n}\n\ncreateRoot(document.getElementById('root')).render(\n <MyForm />\n);\n\nRun \nExample »\n\nExample Explained:\n\nThe first thing to notice is that when using a single useState call, we use an object to hold any initial values.\n In this case, with no initial values, we use an empty object:\n\nconst [inputs, setInputs] = useState({});\n\nNext, the handleChange function is updated to handle multiple input fields.\n\nIn the function, we access the input fields in the event handler using the\n e.target.name and\n e.target.value syntax.\n\nTo update the state, use square brackets [bracket notation] around the property name.\n\nfunction handleChange(e) {\n const name = e.target.name;\n const value = e.target.value;\n setInputs(values => ({...values, [name]: value}))\n}\n\nWhen refering to input values,\n we add the name of the state object, inputs, as well as the name of the input field:\n\n<input \n type=\"text\" \n name=\"firstname\" \n value={inputs.firstname} \n onChange={handleChange}\n/>\n<input \n type=\"text\" \n name=\"lastname\" \n value={inputs.lastname} \n onChange={handleChange}\n/>\n<p>Current values: {inputs.firstname} {inputs.lastname}</p>\n\nAdvertisement\n -->\n\nInitial Values\n\nTo add initial values to the input fields in the example above,\n add the proper keys and values to the useState object:\n\n Example:\n Use initial values for firstname and lastname:\n\n function MyForm() {\n const [inputs, setInputs] = useState({\n firstname: 'John',\n lastname: 'Doe'\n });\n\n ...\n\nRun \nExample »\n\n❮ Previous\nNext ❯\n\n ★\n\n +1\n\n Sign in to track progress",
