                "code": "Example:\nReact uses the checked attribute to control the checkbox:\n\nimport { useState } from 'react';\nimport { createRoot } from 'react-dom/client';\n\nfunction MyForm() {\n const [inputs, setInputs] = useState({});\n\n const handleChange = (e) => {\n const target = e.target;\n const value = target.type === 'checkbox' ? target.checked : target.value;\n const name = target.name;\n setInputs(values => ({...values, [name]: value}))\n }\n\n const handleSubmit = (event) => {\n let fillings = '';\n if (inputs.tomato) fillings += 'tomato';\n if (inputs.onion) {\n if (inputs.tomato) fillings += ' and ';\n fillings += 'onion';\n }\n if (fillings == '') fillings = 'no fillings';\n alert(`${inputs.firstname} wants a burger with ${fillings}`);\n event.preventDefault();\n };\n\n return (\n <form onSubmit={handleSubmit}>\n <label>My name is:\n <input \n type=\"text\" \n name=\"firstname\" \n value={inputs.firstname} \n onChange={handleChange}\n />\n </label>\n\n <p>I want a burger with:</p>\n <label>Tomato:\n <input \n type=\"checkbox\" \n name=\"tomato\" \n checked={inputs.tomato} \n onChange={handleChange}\n />\n </label>\n <label>Onion:\n <input \n type=\"checkbox\" \n name=\"onion\" \n checked={inputs.onion} \n onChange={handleChange}\n />\n </label>\n <button type=\"submit\">Submit\n </form>\n )\n}\n\ncreateRoot(document.getElementById('root')).render(\n <MyForm />\n);\n\nRun \nExample »\n\nAdvertisement\n -->\n\nInitial Values\n\nTo add initial values to the input fields in the example above,\n add the proper keys and values to the useState object:\n\n Example:\n Use initial values for the input fields:\n\n function MyForm() {\n const [inputs, setInputs] = useState({\n firstname: 'John',\n tomato: true,\n onion: false\n });\n\n ...\n\nRun \nExample »\n\n ❮ Previous\n Next ❯\n\n ★\n\n +1\n\n Sign in to track progress",
