                "code": "4. IDE Support\n\nTypeScript:\n\ninterface User {\n name: string;\n email: string;\n sendMessage(msg: string): void;\n}\n\nconst user: User = {\n name: \"John\",\n email: \"john@example.com\",\n sendMessage(msg) {\n console.log(msg);\n }\n};\n\n// IDE shows all available properties\nuser. // Shows: name, email, sendMessage",
