                "code": "5. Function Parameters\n\nTypeScript:\n\nfunction greet(name: string, age: number) {\n return `${name} is ${age} years old`;\n}\n\ngreet(\"John\", 25); // OK\ngreet(\"John\", \"25\"); // Error!",
