                "code": "Example:\n Passing \"props\" through nested components:\n\nimport { useState } from 'react';\nimport { createRoot } from 'react-dom/client';\n\nfunction Component1() {\n const [user, setUser] = useState(\"Linus\");\n\n return (\n <>\n <h1>{`Hello ${user}!`}</h1>\n <Component2 user={user} />\n </>\n );\n}\n\nfunction Component2({ user }) {\n return (\n <>\n <h1>Component 2</h1>\n <Component3 user={user} />\n </>\n );\n}\n\nfunction Component3({ user }) {\n return (\n <>\n <h1>Component 3</h1>\n <h2>{`Hello ${user} again!`}</h2>\n </>\n );\n}\n\ncreateRoot(document.getElementById('root')).render(\n <Component1 />\n);\n\nRun \nExample »\n\nEven though component 2 did not need the state, it had to pass the state along so that it could reach component 3.\n\nAdvertisement\n -->\n\nThe Solution\nThe solution is to create context.\n\nCreate Context\nTo create context, you must Import createContext and initialize \nit:\n\nimport { useState, createContext, useContext } from 'react';\nimport { createRoot } from 'react-dom/client';\n\nconst UserContext = createContext();\n\nNext we'll use the Context Provider to wrap the tree of components that need the state Context.\n\nContext Provider\nWrap child components in the Context Provider and supply the state value.\n\nfunction Component1() {\n const [user, setUser] = useState(\"Linus\");\n\n return (\n <UserContext.Provider value={user}>\n <h1>{`Hello ${user}!`}</h1>\n <Component2 />\n </UserContext.Provider>\n );\n}\n\nNow, all components in this tree will have access to the user Context.\n\nUse the useContext Hook\nIn order to use the Context in a child component, we need to access it using the useContext Hook.\n\nFirst, include the useContext in the import \nstatement:\n\nimport { useState, createContext, useContext } from \"react\";\n\nThen you can access the user Context in all components:\n\nfunction Component3() {\n const user = useContext(UserContext);\n\n return (\n <>\n <h1>Component 3</h1>\n <h2>{`Hello ${user} again!`}</h2>\n </>\n );\n}\n\nFull Example\n\nExample:\n Here is the full example using React Context:\n\nimport { useState, createContext, useContext } from 'react';\nimport { createRoot } from 'react-dom/client';\n\nconst UserContext = createContext();\n\nfunction Component1() {\n const [user, setUser] = useState(\"Linus\");\n\n return (\n <UserContext.Provider value={user}>\n <h1>{`Hello ${user}!`}</h1>\n <Component2 />\n </UserContext.Provider>\n );\n}\n\nfunction Component2() {\n return (\n <>\n <h1>Component 2</h1>\n <Component3 />\n </>\n );\n}\n\nfunction Component3() {\n const user = useContext(UserContext);\n\n return (\n <>\n <h1>Component 3</h1>\n <h2>{`Hello ${user} again!`}</h2>\n </>\n );\n}\n\ncreateRoot(document.getElementById('root')).render(\n <Component1 />\n);\n\nRun \nExample »\n\n❮ Previous\nNext ❯\n\n ★\n\n +1\n\n Sign in to track progress",
